function resolveTarget(bucket, rolloutPercent) {
  if (rolloutPercent <= 0) return 'legacy';
  if (rolloutPercent >= 100) return 'new';
  return bucket < rolloutPercent ? 'new' : 'legacy';
}

function resolveTarget(config, bucket) {
  if (config.target === 'legacy') return 'legacy';
  if (config.rolloutPercent === undefined || config.rolloutPercent >= 100) return 'new';
  if (config.rolloutPercent <= 0) return 'legacy';
  return bucket < config.rolloutPercent ? 'new' : 'legacy';
}

function matchRate(log) {
  if (log.length === 0) return 1;
  const matches = log.filter((r) => r.matched).length;
  return matches / log.length;
}

function matchRateForPath(log, path) {
  const relevant = log.filter((r) => r.path === path);
  if (relevant.length === 0) return 1;
  const matches = relevant.filter((r) => r.matched).length;
  return matches / relevant.length;
}

function mismatchesForPath(log, path) {
  return log.filter((r) => r.path === path && !r.matched);
}

